1	/**
2	 * OAuth 2.0 ユーティリティ関数
3	 * JWT トークンの生成・検証、PKCE、ランダム文字列生成など
4	 */
5	
6	import jwt from 'jsonwebtoken';
7	import crypto from 'crypto';
8	import bcrypt from 'bcryptjs';
9	
10	// 環境変数から JWT シークレットキーを取得
11	const JWT_SECRET = process.env.JWT_SECRET;
12	if (!JWT_SECRET) {
13	  throw new Error('JWT_SECRET environment variable is required');
14	}
15	const JWT_ISSUER = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000';
16	
17	// 許可されるOAuthスコープ
18	const ALLOWED_SCOPES = ['openid', 'profile'] as const;
19	type AllowedScope = typeof ALLOWED_SCOPES[number];
20	
21	/**
22	 * スコープ文字列を検証し、許可されたスコープのみを返す
23	 */
24	export function validateScope(scope: string): string {
25	  const requested = scope.split(' ').filter(Boolean);
26	  const valid = requested.filter((s): s is AllowedScope =>
27	    (ALLOWED_SCOPES as readonly string[]).includes(s)
28	  );
29	  if (valid.length === 0) {
30	    return 'openid profile';
31	  }
32	  return [...new Set(valid)].join(' ');
33	}
34	
35	// トークン有効期限
36	export const TOKEN_EXPIRY = {
37	  ACCESS_TOKEN: 60 * 60 * 24 * 30, // 30日（秒）
38	  AUTHORIZATION_CODE: 60 * 10, // 10分（秒）
39	};
40	
41	/**
42	 * ランダムな文字列を生成（client_id, client_secret, codeなど）
43	 */
44	export function generateRandomString(length: number = 32): string {
45	  return crypto.randomBytes(length).toString('hex');
46	}
47	
48	/**
49	 * Client Secret をハッシュ化
50	 */
51	export async function hashClientSecret(secret: string): Promise<string> {
52	  return bcrypt.hash(secret, 10);
53	}
54	
55	/**
56	 * Client Secret を検証
57	 */
58	export async function verifyClientSecret(
59	  secret: string,
60	  hash: string
61	): Promise<boolean> {
62	  return bcrypt.compare(secret, hash);
63	}
64	
65	/**
66	 * PKCE code_challenge を検証
67	 */
68	export function verifyCodeChallenge(
69	  verifier: string,
70	  challenge: string,
71	  method: string = 'S256'
72	): boolean {
73	  if (method !== 'S256') {
74	    return false;
75	  }
76	
77	  const hash = crypto
78	    .createHash('sha256')
79	    .update(verifier)
80	    .digest('base64url');
81	
82	  return hash === challenge;
83	}
84	
85	/**
86	 * JWT アクセストークンを生成
87	 */
88	export interface JWTPayload {
89	  sub: string; // user_id
90	  display_name: string;
91	  discord_id: string;
92	  generation: number;
93	  status: number;
94	  scope: string;
95	}
96	
97	export function generateAccessToken(
98	  payload: JWTPayload,
99	  clientId: string
100	): string {
101	  const now = Math.floor(Date.now() / 1000);
102	
103	  return jwt.sign(
104	    {
105	      ...payload,
106	      iss: JWT_ISSUER,
107	      aud: clientId,
108	      iat: now,
109	      exp: now + TOKEN_EXPIRY.ACCESS_TOKEN,
